CREATE DATABASE IF NOT EXISTS bk_ids CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bk_ids;
CREATE TABLE IF NOT EXISTS base_roles ( role_id INT AUTO_INCREMENT PRIMARY KEY, role_name VARCHAR(50) NOT NULL, role_desc TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS base_users ( usr_id INT AUTO_INCREMENT PRIMARY KEY, usr_login VARCHAR(50) NOT NULL UNIQUE, usr_pwd VARCHAR(255) NOT NULL, usr_name VARCHAR(100) NOT NULL, role_id INT NOT NULL, usr_enabled TINYINT(1) DEFAULT 1, FOREIGN KEY (role_id) REFERENCES base_roles(role_id) ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS encoding (encoding_type INT PRIMARY KEY, encoding_text VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS signature (sig_id INT AUTO_INCREMENT PRIMARY KEY, sig_name VARCHAR(255) NOT NULL, sig_class_id INT NOT NULL, sig_priority INT, sig_rev INT, sig_sid INT, sig_gid INT, INDEX idx_sig_name (sig_name));
CREATE TABLE IF NOT EXISTS sensor (sid INT AUTO_INCREMENT PRIMARY KEY, hostname VARCHAR(255), interface VARCHAR(50), filter VARCHAR(255), detail INT, encoding INT, last_cid BIGINT, FOREIGN KEY (encoding) REFERENCES encoding(encoding_type));
CREATE TABLE IF NOT EXISTS event (sid INT NOT NULL, cid BIGINT AUTO_INCREMENT PRIMARY KEY, signature INT NOT NULL, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (sid) REFERENCES sensor(sid), FOREIGN KEY (signature) REFERENCES signature(sig_id), INDEX idx_timestamp (timestamp));
CREATE TABLE IF NOT EXISTS data (sid INT NOT NULL, cid BIGINT NOT NULL, data_payload TEXT, PRIMARY KEY (cid), FOREIGN KEY (cid) REFERENCES event(cid) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS iphdr (sid INT NOT NULL, cid BIGINT NOT NULL, ip_src VARCHAR(45) NOT NULL, ip_dst VARCHAR(45) NOT NULL, ip_ver INT, ip_hlen INT, ip_tos INT, ip_len INT, ip_id INT, ip_flags INT, ip_off INT, ip_ttl INT, ip_proto INT NOT NULL, ip_csum INT, PRIMARY KEY (cid), FOREIGN KEY (cid) REFERENCES event(cid) ON DELETE CASCADE, INDEX idx_ip_src (ip_src), INDEX idx_ip_dst (ip_dst));
CREATE TABLE IF NOT EXISTS tcphdr (sid INT NOT NULL, cid BIGINT NOT NULL, tcp_sport INT NOT NULL, tcp_dport INT NOT NULL, tcp_seq BIGINT, tcp_ack BIGINT, tcp_off INT, tcp_res INT, tcp_flags INT NOT NULL, tcp_win INT, tcp_csum INT, tcp_urp INT, PRIMARY KEY (cid), FOREIGN KEY (cid) REFERENCES event(cid) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS udphdr (sid INT NOT NULL, cid BIGINT NOT NULL, udp_sport INT NOT NULL, udp_dport INT NOT NULL, udp_len INT, udp_csum INT, PRIMARY KEY (cid), FOREIGN KEY (cid) REFERENCES event(cid) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS icmphdr (sid INT NOT NULL, cid BIGINT NOT NULL, icmp_type INT NOT NULL, icmp_code INT NOT NULL, icmp_csum INT, icmp_id INT NOT NULL, icmp_seq INT NOT NULL, PRIMARY KEY (cid), FOREIGN KEY (cid) REFERENCES event(cid) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS misuse_alerts ( id BIGINT AUTO_INCREMENT PRIMARY KEY, timestamp DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, ip_src VARCHAR(45) NOT NULL, src_port INT, ip_dst VARCHAR(45) NOT NULL, dst_port INT, protocol VARCHAR(20), sig_name VARCHAR(255), action VARCHAR(50) DEFAULT 'ALERT', raw_payload TEXT, INDEX idx_time (timestamp), INDEX idx_ip (ip_src) );
CREATE TABLE IF NOT EXISTS acid_ip_cache (ipc_ip VARCHAR(45) PRIMARY KEY, ipc_fqdn VARCHAR(255), ipc_dns_timestamp DATETIME, ipc_whois TEXT, ipc_whois_timestamp DATETIME);
CREATE TABLE IF NOT EXISTS ids_cauhinh ( id INT AUTO_INCREMENT PRIMARY KEY, thoigian_quet INT NOT NULL DEFAULT 5, nguong FLOAT NOT NULL DEFAULT 700.0, thoigian_hientai DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS ids_dulieu ( id BIGINT AUTO_INCREMENT PRIMARY KEY, soluong_tcp INT NOT NULL DEFAULT 0, soluong_udp INT NOT NULL DEFAULT 0, soluong_icmp INT NOT NULL DEFAULT 0, tg_batdau DATETIME NOT NULL, tg_ketthuc DATETIME NOT NULL, Si FLOAT DEFAULT 0, Gn FLOAT DEFAULT 0, entropi TEXT, top_ip VARCHAR(45), sample_hex LONGTEXT, INDEX idx_thongke_thoi_gian (tg_batdau, tg_ketthuc), INDEX idx_top_ip (top_ip) );
CREATE TABLE IF NOT EXISTS rules (id BIGINT AUTO_INCREMENT PRIMARY KEY, sid INT UNIQUE, rev INT DEFAULT 1, action VARCHAR(10), protocol VARCHAR(10), src_net VARCHAR(50) DEFAULT 'any', src_port VARCHAR(20) DEFAULT 'any', dst_net VARCHAR(50) DEFAULT 'any', dst_port VARCHAR(20) DEFAULT 'any', msg VARCHAR(255), raw_rule TEXT NOT NULL, source ENUM('local_custom', 'threat_intel', 'community', 'auto_generated') DEFAULT 'local_custom', enabled TINYINT(1) DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_sid (sid), INDEX idx_source (source));
CREATE TABLE IF NOT EXISTS ips_bans (id BIGINT AUTO_INCREMENT PRIMARY KEY, ip VARCHAR(45) NOT NULL UNIQUE, attack_type VARCHAR(100), first_seen DATETIME, last_seen DATETIME, ban_start DATETIME, ban_end DATETIME, status ENUM('ACTIVE', 'UNBLOCKED', 'EXPIRED') DEFAULT 'ACTIVE', source VARCHAR(50), INDEX idx_ip (ip), INDEX idx_status (status));
CREATE TABLE IF NOT EXISTS packet_forensics (id BIGINT AUTO_INCREMENT PRIMARY KEY, ip_src VARCHAR(45), ip_dst VARCHAR(45), protocol VARCHAR(20), src_port INT, dst_port INT, capture_time DATETIME, hex_dump LONGTEXT, ascii_payload TEXT, sensor_id INT, INDEX idx_ip_src (ip_src), INDEX idx_time (capture_time));
CREATE TABLE IF NOT EXISTS ids_incidents (id BIGINT AUTO_INCREMENT PRIMARY KEY, incident_type VARCHAR(100), severity ENUM('LOW', 'MEDIUM', 'HIGH', 'CRITICAL'), source_engine VARCHAR(50), description TEXT, related_ip VARCHAR(45), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, resolved_at DATETIME, status ENUM('OPEN', 'INVESTIGATING', 'RESOLVED') DEFAULT 'OPEN', INDEX idx_ip (related_ip), INDEX idx_status (status));
CREATE TABLE IF NOT EXISTS ids_metrics (id BIGINT AUTO_INCREMENT PRIMARY KEY, metric_name VARCHAR(100), metric_value FLOAT, recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_metric (metric_name));
INSERT IGNORE INTO ids_cauhinh (id, thoigian_quet, nguong) VALUES (1, 5, 700);
